rule.definition:
a!localVariables(
  local!queryDataSubset:#"SYSTEM_SYSRULES_queryEntity_v1"(
    entity: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050377",
    fetchtotalcount: ri!fetchTotalCount,
    query: #"SYSTEM_SYSRULES_query"(
      selection: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!columns),
        {},
        #"SYSTEM_SYSRULES_querySelection"(
          columns: #"SYSTEM_SYSRULES_forEach"(
            items: ri!columns,
            expression: #"SYSTEM_SYSRULES_queryColumn"(field:fv!item)
          )
        )
      ),
      logicalExpression: #"SYSTEM_SYSRULES_queryLogicalExpression"(
        operator: "AND",
        ignorefilterswithemptyvalues: true,
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "userId", 
            operator: "=", 
            value: ri!userId, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "userName", 
            operator: "=", 
            value: ri!userName, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "roleId", 
            operator: "in", 
            value: ri!roleId, 
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "isActive",
            operator: "=",
            value: ri!isActive
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "firstName",
            operator: "starts with",
            value: ri!searchFirstName
          ),
          #"SYSTEM_SYSRULES_queryFilter"(
            field: "lastName",
            operator: "starts with",
            value: ri!searchLastName
          )
        }
      ),
      paginginfo: if(
        #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!pagingInfo),
        #"SYSTEM_SYSRULES_pagingInfo"(
          startIndex: 1,
          batchSize: -1,
          sort: {
            #"SYSTEM_SYSRULES_sortInfo"(
              field: "userId",
              ascending: true
            )
          },
        ),
        ri!pagingInfo
      )
    )
  ),
  if(
    ri!returnCDT,
    cast(
      'type!{urn:com:appian:types:CAW}CAW_User?list',
      local!queryDataSubset.data
    ),
    local!queryDataSubset
  )
)
